export function findBiomedicalTaxonomiesById(id: string): BiomedicalCohortRecord | undefined {
  return BIOMEDICAL_COHORTS_DATABASE.find(item => item.id === id);
}

export function getAllBiomedicalTaxonomiesRecords(): BiomedicalCohortRecord[] {
  return BIOMEDICAL_COHORTS_DATABASE;
}

export function filterBiomedicalTaxonomiesByPredicate(predicate: (item: BiomedicalCohortRecord) => boolean): BiomedicalCohortRecord[] {
  return BIOMEDICAL_COHORTS_DATABASE.filter(predicate);
}

export function countBiomedicalTaxonomiesRecords(): number {
  return BIOMEDICAL_COHORTS_DATABASE.length;
}
